item.description:
The host accessibility by ICMP ping.

0 - ICMP ping fails;
1 - ICMP ping successful.

trigger_prototype.expression:
avg(/Cisco IOS by SNMP Modified/sensor.temp.value[ciscoEnvMonTemperatureValue.{#SNMPINDEX}],5m)>{$TEMP_CRIT:"{#SNMPVALUE}"}
or
last(/Cisco IOS by SNMP Modified/sensor.temp.status[ciscoEnvMonTemperatureState.{#SNMPINDEX}])={$TEMP_CRIT_STATUS}
or
last(/Cisco IOS by SNMP Modified/sensor.temp.status[ciscoEnvMonTemperatureState.{#SNMPINDEX}])={$TEMP_DISASTER_STATUS}

avg(/Cisco IOS by SNMP Modified/sensor.temp.value[ciscoEnvMonTemperatureValue.{#SNMPINDEX}],5m)>{$TEMP_WARN:"{#SNMPVALUE}"}
or
last(/Cisco IOS by SNMP Modified/sensor.temp.status[ciscoEnvMonTemperatureState.{#SNMPINDEX}])={$TEMP_WARN_STATUS}

dependency.expression:
avg(/Cisco IOS by SNMP Modified/sensor.temp.value[ciscoEnvMonTemperatureValue.{#SNMPINDEX}],5m)>{$TEMP_CRIT:"{#SNMPVALUE}"}
or
last(/Cisco IOS by SNMP Modified/sensor.temp.status[ciscoEnvMonTemperatureState.{#SNMPINDEX}])={$TEMP_CRIT_STATUS}
or
last(/Cisco IOS by SNMP Modified/sensor.temp.status[ciscoEnvMonTemperatureState.{#SNMPINDEX}])={$TEMP_DISASTER_STATUS}
